for r in risks:r['score']=r['likelihood']*r['impact'];r['residualScore']=None;r['mitigationApplied']=False
(base/'risk-register.initial.json').write_text(json.dumps(risks,indent=2)+'\n')
headers=['ID','Category','Cause / Event / Consequence','Affected Component','Evidence','Status','Likelihood','Impact','Score','Mitigation','Owner','Verification']
rows=[]
for r in risks: rows.append([r['id'],r['category'],r['cause']+' / '+r['event']+' / '+r['consequence'],r['component'],r['evidence'],r['status'],r['likelihood'],r['impact'],r['score'],r['mitigation'],r['owner'],r['verification']])
with (base/'risk-register.initial.csv').open('w',newline='') as f:w=csv.writer(f);w.writerow(headers);w.writerows(rows)
text='# Initial risk register\n\nScoring: likelihood 1 unlikely, 2 possible, 3 likely; impact 1 minor, 2 moderate, 3 serious; score = likelihood × impact, maximum 9. These are initial scores before approval and mitigation. Evidence paths below are relative to evidence/verification unless noted otherwise.\n\n'
text+='| '+' | '.join(headers)+' |\n|'+ '|'.join(['---']*len(headers))+'|\n'
for row in rows:text+='| '+' | '.join(str(x).replace('|','/') for x in row)+' |\n'
text+='\n## Score justification and priority\n\n'
for r in risks:text+=f"**{r['id']} — {r['likelihood']} × {r['impact']} = {r['score']}.** {r['reason']}\n\n"
text+='R1 and R2 are selected among the three equal-score confirmed findings. R1 removes the reproduced verification barrier and makes evidence repeatable; R2 supplies the explicit agent review/isolation controls required by this exercise. R3 remains a separately owned security item: the audit does not pretend that CI or documentation upgrades dependency versions. A toolchain upgrade may cross major versions and needs its own compatibility review. No residual reduction is recorded before the selected patches are approved, applied and tested.\n'
(base/'risk-register.initial.md').write_text(text)
